function initializeDiseaseFocus(){const focus=diseaseFocus[document.body.dataset.focus];if(!focus)return false;area=focus.area;$('search').value=focus.condition;$('search').setAttribute('aria-label','Filter therapies within '+focus.name);$('search').placeholder='Filter by therapy, target, or keyword';$('headerQuery').value=focus.condition;$('contextArea').textContent=focus.name;$('trialHeading').textContent=focus.name+' clinical trials';$('trialSort').value='LastUpdatePostDate:desc';$('trialWindow').value='';$('modality').value='THERAPEUTIC';$('focusOverview').innerHTML=`<div class="focus-intro panel"><span class="eyebrow">Research landscape</span><p>${esc(focus.summary)}</p><p class="note">Background reviewed November 22, 2026 · <a href="${focus.source}" target="_blank" rel="noopener">${esc(focus.sourceLabel)}</a>. Pathways are a starting guide, not a complete treatment list. Trial links use keyword matching; confirm the mechanism and eligibility in each record.</p></div><div class="focus-pathways">${focus.pathways.map(([name,target,description,query],i)=>`<article class="panel focus-pathway"><span class="eyebrow">${esc(target)}</span><h2>${esc(name)}</h2><p>${esc(description)}</p><button class="outline" data-pathway="${i}">${query?'Explore matching trials':'Browse all therapeutic trials'}</button></article>`).join('')}</div><div class="focus-tools panel"><div><h2>Read the evidence, not just the headline</h2><p>${esc(focus.watch)}</p><p class="note">Use Compare on up to three trial cards. Registered endpoints are planned measures; posted results are labeled separately. Registry status is sponsor-reported.</p></div><div><button class="outline" id="focusAll">All ${esc(focus.name)} trials</button><a class="outline" href="${new URL('molecules/',appBase)}?compound=${encodeURIComponent(focus.compound)}">Inspect ${esc(focus.compound)} molecule</a></div></div><p class="note">Research information only. A listed study does not establish that a therapy works or that you are eligible. A clinical team must assess participation.</p>`;
 const conditionQuery=trialQueryParams;trialQueryParams=function(){const params=conditionQuery();if(exactTrialId())return params;params.set('query.cond',focus.condition);const term=$('search').value.trim();if(term&&term.toLowerCase()!==focus.condition.toLowerCase())params.set('query.intr',term);return params};
 document.querySelectorAll('[data-pathway]').forEach(b=>b.onclick=()=>{$('search').value=focus.pathways[Number(b.dataset.pathway)][3]||focus.condition;loadTrials();$('explorer').scrollIntoView({block:'start',behavior:'smooth'})});$('focusAll').onclick=()=>{$('search').value=focus.condition;loadTrials()};loadTrials();return true}
